const prs = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const deja = l => (l || []).some(x => x.name === 'qualite:verifiee' || x.name === 'qualite:refusee');
const a_faire = prs.filter(p => p && p.number && !deja(p.labels));
return a_faire.map(p => ({ json: { pr: p.number, titre: p.title, branche: p.head.ref, sha: p.head.sha } }));

const fichiers = $input.all().map(i => i.json);
const ctx = $('3. Écarter les PR déjà vérifiées').first().json;

const estTest = f => /(^|\/)tests?\//.test(f) || /(^|\/)(specs?)\.(py|js|ts)$/.test(f) || /(^|\/)test_[^\/]*$/.test(f) || /_test\.(py|js|ts)$/.test(f);
const estCode = f => /\.(py|js|ts|tsx|html|css)$/.test(f) && !estTest(f);

const tous = fichiers.map(f => f.filename);
const code = tous.filter(estCode);
const tests = tous.filter(estTest);

const motifs = [
  ['sk-', /sk-[A-Za-z0-9]{16,}/],
  ['jeton GitHub', /(ghp_|github_pat_)[A-Za-z0-9_]{12,}/],
  ['mot de passe en dur', /(password|passwd)\s*=\s*['"][^'"]{6,}/i],
  ['cle de service', /service_role/],
];
const secrets = [];
const aFaire = [];
for (const f of fichiers) {
  const patch = f.patch || '';
  for (const [nom, re] of motifs) if (re.test(patch) && !secrets.includes(nom)) secrets.push(nom);
  if (/^\+.*\b(TODO|FIXME)\b/m.test(patch)) aFaire.push(f.filename);
}

const refus = [];
if (code.length && !tests.length) {
  refus.push(`Aucun fichier de test modifié alors que ${code.length} fichier(s) de code le sont : ${code.slice(0, 5).join(', ')}`);
}
if (secrets.length) {
  refus.push(`Secret potentiel détecté dans le diff : ${secrets.join(', ')}`);
}

const verdict = refus.length ? 'qualite:refusee' : 'qualite:verifiee';
const lignes = [
  '## Garde-fou qualité',
  '',
  `- Fichiers de code modifiés : ${code.length}`,
  `- Fichiers de test modifiés : ${tests.length}`,
  `- Secret potentiel : ${secrets.length ? secrets.join(', ') : 'aucun'}`,
  `- TODO/FIXME ajoutés : ${aFaire.length ? aFaire.join(', ') : 'aucun'}`,
  '',
];
if (refus.length) {
  lignes.push('### Refusé', '');
  refus.forEach(r => lignes.push(`- ${r}`));
  lignes.push('', '_Corriger puis retirer l étiquette `qualite:refusee` pour relancer la vérification._');
} else {
  lignes.push('_Vérification passée : chaque modification de code est accompagnée d un test._');
}
lignes.push('', '---', '_Contrôle déterministe : aucune IA appelée, coût 0 jeton._');

return [{ json: { ...ctx, verdict, corps: lignes.join('\n') } }];
